function cloudErrorText(error){
 const code=String(error?.payload?.error||error?.message||'').trim();
 if(code==='rate_limited')return `Muitas tentativas em pouco tempo. Aguarde ${Number(error?.payload?.retryAfterSeconds||30)}s e tente novamente.`;
 if(code==='personal_data_in_public_text')return error?.payload?.message||'Remova e-mail, telefone ou CPF do título/descrição.';
 if(code==='invalid_image_type'||code==='invalid_image_signature')return 'Use apenas imagem JPG, PNG ou WebP válida.';
 if(code==='invalid_image_size'||code==='payload_too_large')return 'A foto excede o limite de 1,5 MB.';
 if(code.includes('invalid_')||code.includes('incomplete_'))return 'Revise os campos informados e tente novamente.';
 return 'Não foi possível enviar ao backend agora. O rascunho foi preservado.';
}
function remoteToOccurrence(row,previous=null){
 if(!row)return null;
 const history=Array.isArray(row.history)?row.history.map(h=>[h.status,h.created_at,h.note||'Atualização registrada.']):(previous?.history||[]);
 return {protocol:String(row.protocol||'').toUpperCase(),title:row.title||previous?.title||'',category:row.category_slug||row.categories?.slug||previous?.category||'outros',bairro:row.neighborhood_label||previous?.bairro||'',address:row.public_location||'',description:row.description||previous?.description||'',status:row.status||previous?.status||'Recebida',agency:row.responsible_agency||previous?.agency||'A definir',created:row.created_at||previous?.created||new Date().toISOString(),updated:row.updated_at||previous?.updated||null,public:true,lat:Number.isFinite(Number(row.public_latitude))?Number(row.public_latitude):(previous?.lat??null),lng:Number.isFinite(Number(row.public_longitude))?Number(row.public_longitude):(previous?.lng??null),photo:previous?.photo||'',localOwner:Boolean(previous?.localOwner),cloudOrigin:true,moderationStatus:row.moderation_status||previous?.moderationStatus||'approved',territoryResolutionStatus:row.territory_resolution_status||previous?.territoryResolutionStatus||'unresolved',privateData:previous?.privateData||{},history};
}
async function fetchCloudOccurrence(protocol,trackingKey=null){
 const api=cloudApi();if(!api?.trackOccurrence||!api.state?.connected)return null;
 const row=await api.trackOccurrence(protocol,trackingKey);return row?remoteToOccurrence(row,findProtocol(protocol)):null;
}
function publicMetricRecords(){return db.occurrences.filter(o=>!o.cloudOrigin||o.moderationStatus==='approved')}
async function syncPublicCloudOccurrences(){
 const api=cloudApi();if(!api?.listPublicOccurrences)return 0;
 try{
  if(api.health&&!api.state?.connected)await api.health();if(!api.state?.connected)return 0;
  const rows=await api.listPublicOccurrences(250);if(!Array.isArray(rows))return 0;let changed=0;
  for(const row of rows){const protocol=String(row.protocol||'').toUpperCase();if(!protocol)continue;const idx=db.occurrences.findIndex(o=>String(o.protocol).toUpperCase()===protocol),previous=idx>=0?db.occurrences[idx]:null,mapped=remoteToOccurrence(row,previous);if(previous?.localOwner){mapped.localOwner=true;mapped.privateData=previous.privateData||{}}if(idx>=0)db.occurrences[idx]=mapped;else db.occurrences.push(mapped);changed++}
  if(changed){db.occurrences.sort((a,b)=>new Date(b.created)-new Date(a.created));window.CidadeConectaLocalDB=db;saveDB()}return changed;
 }catch(error){console.warn('Sincronização pública indisponível:',String(error?.message||error));return 0}
}
