 '<article class="card dashboardPanelV51 agencyLoadV54"><div class="panelHeadV51"><div><span class="miniLabel">Competências</span><h2>Distribuição por área de referência</h2></div><a class="miniLink" href="#/rede-municipal">ver rede →</a></div><div class="agencyLoadBarsV54">'+agencyGroups.map((x,i)=>'<div><span><i>'+String(i+1).padStart(2,'0')+'</i>'+esc(x.label)+'</span><b>'+x.count+'</b><em><i style="width:'+Math.round(x.count/maxAgency*100)+'%"></i></em></div>').join('')+'</div><p class="small muted">Distribuição do protótipo por competência de referência; não representa carga real de trabalho das secretarias.</p></article></div></div></section>'
