function openCommand(){const overlay=$('#commandPalette');if(!overlay)return;overlay.classList.remove('hidden');document.body.classList.add('commandOpenV53');const input=$('#commandInput');input.value='';renderCommand('');setTimeout(()=>input.focus(),20)}
