 const markers=[];records.forEach(o=>{const marker=L.marker([o.lat,o.lng],{icon:mapMarkerIcon(o.status)}).addTo(currentMap).bindTooltip(esc(o.title),{direction:'top'});marker.on('click',()=>location.hash='#/ocorrencia/'+encodeURIComponent(o.protocol));markers.push(marker)});
