 ['bairro','title','description','address','name','email','phone'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{counters();updateCompletion();if(id==='bairro')updateSimilar()}));$('#agree')?.addEventListener('change',updateCompletion);
