function collectDraft(chosen){return{category:$('#category').value,bairro:$('#bairro').value,title:$('#title').value,description:$('#description').value,address:$('#address').value,name:$('#name').value,email:$('#email').value,phone:$('#phone').value,lat:chosen.lat,lng:chosen.lng,savedAt:new Date().toISOString()}}
