function bindFollow(){$('#followForm').onsubmit=async e=>{e.preventDefault();const protocol=$('#protocolInput').value.trim().toUpperCase(),box=$('#followResult');let o=findProtocol(protocol);box.innerHTML='<div class="card empty"><p class="muted">Consultando o protocolo com segurança...</p></div>';try{const api=cloudApi();if(api?.health&&!api.state?.connected)await api.health();if(api?.state?.connected&&api?.trackOccurrence){const remote=await fetchCloudOccurrence(protocol,trackingKeyFor(protocol));if(remote){if(o?.localOwner){remote.localOwner=true;remote.privateData=o.privateData||{}}o=remote}}}catch(error){console.warn('Falha no acompanhamento:',String(error?.message||error))}box.innerHTML=o?detail(o):'<div class="card empty"><h2>Protocolo não encontrado</h2><p class="muted">Confira o código. Registros pendentes criados em outro navegador exigem o código privado salvo no dispositivo de origem.</p></div>';bindGlobalPageActions();if(o)setTimeout(()=>initDetailMap(o),0)}}
function initDetailMap(o){if(!Number.isFinite(o.lat)||!Number.isFinite(o.lng)||!$('#detailMap')||!window.L)return;currentMap=L.map('detailMap',{scrollWheelZoom:false}).setView([o.lat,o.lng],16);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(currentMap);L.marker([o.lat,o.lng],{icon:mapMarkerIcon(o.status)}).addTo(currentMap).bindPopup(esc(o.title)).openPopup()}
