 function setQueryFromUrl(){if(query.get('q'))$('#mapSearch').value=query.get('q');if(query.get('cat'))$('#mapCat').value=query.get('cat');if(query.get('status'))$('#mapStatus').value=query.get('status');if(query.get('region'))$('#mapRegion').value=query.get('region');if(query.get('agency'))$('#mapAgency').value=query.get('agency');if(query.get('open')==='1')$('#mapOpenOnly').checked=true;if(query.get('cluster')==='0')$('#mapCluster').checked=false}
 function syncUrl(){const q=new URLSearchParams(),search=$('#mapSearch').value.trim(),catv=$('#mapCat').value,status=$('#mapStatus').value,region=$('#mapRegion')?.value,agency=$('#mapAgency')?.value;if(search)q.set('q',search);if(catv)q.set('cat',catv);if(status)q.set('status',status);if(region)q.set('region',region);if(agency)q.set('agency',agency);if($('#mapOpenOnly')?.checked)q.set('open','1');if($('#mapCluster')&&!$('#mapCluster').checked)q.set('cluster','0');history.replaceState(null,'','#/mapa'+(q.toString()?'?'+q.toString():''))}
 function regionMatch(o){const selected=$('#mapRegion')?.value;if(!selected)return true;if(!territoryIndex)return false;const ids=territoryIndex.get(normText(o.bairro))||[];return ids.includes(Number(selected))}
 function filtered(){const q=$('#mapSearch').value.trim().toLowerCase(),c=$('#mapCat').value,s=$('#mapStatus').value,agency=$('#mapAgency')?.value,openOnly=$('#mapOpenOnly')?.checked;let arr=publicMetricRecords().filter(o=>Number.isFinite(o.lat)&&Number.isFinite(o.lng)&&(!q||(o.title+' '+o.bairro+' '+o.protocol).toLowerCase().includes(q))&&(!c||o.category===c)&&(!s||o.status===s)&&(!agency||routingReference(o.category).agencyId===agency)&&(!openOnly||o.status!=='Resolvida')&&regionMatch(o));if(userPoint)arr=arr.map(o=>Object.assign({},o,{_distance:distanceKm(userPoint.lat,userPoint.lng,o.lat,o.lng)})).sort((a,b)=>a._distance-b._distance);return arr}
 function clusterGroups(arr){const zoom=currentMap.getZoom(),enabled=$('#mapCluster')?.checked!==false;if(!enabled||zoom>=14)return arr.map(o=>[o]);const cell=zoom<=10?.09:zoom===11?.055:zoom===12?.032:.018,map=new Map();for(const o of arr){const key=Math.round(o.lat/cell)+':'+Math.round(o.lng/cell),g=map.get(key)||[];g.push(o);map.set(key,g)}return[...map.values()]}
 function clusterIcon(group){const open=group.filter(o=>o.status!=='Resolvida').length,size=group.length>=10?54:group.length>=5?50:46;return L.divIcon({className:'ccClusterWrapV55',html:'<span class="ccClusterV55"><b>'+group.length+'</b><small>'+open+' aberta'+(open===1?'':'s')+'</small></span>',iconSize:[size,size],iconAnchor:[size/2,size/2]})}
 function updateSummary(arr,groups){const active=arr.filter(o=>o.status!=='Resolvida').length,hoods=new Set(arr.map(o=>o.bairro).filter(Boolean)).size,filtersCount=[$('#mapSearch').value.trim(),$('#mapCat').value,$('#mapStatus').value,$('#mapRegion')?.value,$('#mapAgency')?.value,$('#mapOpenOnly')?.checked].filter(Boolean).length;$('#mapActiveFilters').textContent=filtersCount?filtersCount+' filtro(s) ativo(s)':'Nenhum filtro ativo';$('#mapMiniStats').innerHTML='<span><b>'+arr.length+'</b> visíveis</span><span><b>'+active+'</b> abertas</span><span><b>'+hoods+'</b> bairros</span>'}
 function renderResults(arr,groups){const count=$('#mapResultCount'),out=$('#mapResults');if(count)count.textContent=String(arr.length);updateSummary(arr,groups);if(!out)return;if(!arr.length){out.innerHTML='<div class="mapEmpty">Nenhuma ocorrência encontrada com estes filtros.</div>';return}out.innerHTML=arr.map(o=>'<div class="mapResultItem mapResultItemV55"><button type="button" data-map-open="'+esc(o.protocol)+'"><span class="mapResultIcon">'+catIcon(o.category)+'</span><span class="mapResultMain"><b>'+esc(o.title)+'</b><small>'+esc(o.bairro)+' · '+esc(o.protocol)+' · '+esc(routingReference(o.category).agencyLabel)+'</small></span><span class="mapResultMeta">'+(o._distance!=null?o._distance.toFixed(1)+' km':esc(o.status))+'</span></button><a href="#/bairro?nome='+encodeURIComponent(o.bairro)+'" aria-label="Abrir radar do bairro '+esc(o.bairro)+'">Bairro →</a></div>').join('');$$('[data-map-open]').forEach(b=>b.onclick=()=>focusOccurrence(b.dataset.mapOpen))}
 function addSingle(o){const popup='<div class="mapPopupV50 mapPopupV55"><span class="popupCategory">'+catIcon(o.category)+' '+esc(cat(o.category)[2])+'</span><b>'+esc(o.title)+'</b><small>'+esc(o.bairro)+' · '+esc(o.protocol)+'</small><div class="popupAgencyV54">'+iconSvg('layers')+' '+esc(routingReference(o.category).agencyLabel)+'</div><div>'+badge(o.status)+'</div><div class="mapPopupActionsV55"><a href="#/ocorrencia/'+encodeURIComponent(o.protocol)+'">Abrir ocorrência →</a><a href="#/bairro?nome='+encodeURIComponent(o.bairro)+'">Radar do bairro →</a></div></div>';const marker=L.marker([o.lat,o.lng],{icon:mapMarkerIcon(o.status)}).addTo(currentMap).bindPopup(popup,{maxWidth:310});markers.push(marker);markerByProtocol.set(o.protocol,marker);return marker}
 function addCluster(group){const lat=group.reduce((s,o)=>s+o.lat,0)/group.length,lng=group.reduce((s,o)=>s+o.lng,0)/group.length,marker=L.marker([lat,lng],{icon:clusterIcon(group),keyboard:true,title:group.length+' ocorrências próximas'}).addTo(currentMap);marker.on('click',()=>{const bounds=L.latLngBounds(group.map(o=>[o.lat,o.lng]));currentMap.fitBounds(bounds.pad(.45),{maxZoom:16})});markers.push(marker);return marker}
 function draw(fit=true){markers.forEach(m=>currentMap.removeLayer(m));markers=[];markerByProtocol.clear();const arr=filtered(),groups=clusterGroups(arr);lastRows=arr;for(const group of groups){if(group.length>1)addCluster(group);else addSingle(group[0])}renderResults(arr,groups);syncUrl();if(fit&&arr.length){currentMap.fitBounds(L.latLngBounds(arr.map(o=>[o.lat,o.lng])).pad(.18),{maxZoom:15})}else if(fit)currentMap.setView(PIRACICABA,12)}
 function focusOccurrence(protocol){const o=lastRows.find(x=>x.protocol===protocol)||publicMetricRecords().find(x=>x.protocol===protocol);if(!o)return;const marker=markerByProtocol.get(protocol);if(marker){currentMap.flyTo(marker.getLatLng(),16,{duration:.65});setTimeout(()=>marker.openPopup(),350)}else{currentMap.flyTo([o.lat,o.lng],16,{duration:.65});setTimeout(()=>{draw(false);markerByProtocol.get(protocol)?.openPopup()},750)}$$('[data-map-open]').forEach(x=>x.closest('.mapResultItemV55')?.classList.toggle('active',x.dataset.mapOpen===protocol))}
 setQueryFromUrl();$$('[data-map-status]').forEach(x=>x.classList.toggle('active',x.dataset.mapStatus===$('#mapStatus').value));$$('[data-map-region]').forEach(x=>x.classList.toggle('active',x.dataset.mapRegion===$('#mapRegion').value));
 ['mapSearch','mapCat','mapStatus','mapRegion','mapAgency','mapOpenOnly','mapCluster'].forEach(id=>$('#'+id)?.addEventListener(id==='mapSearch'?'input':'change',()=>{if(id==='mapRegion')$$('[data-map-region]').forEach(x=>x.classList.toggle('active',x.dataset.mapRegion===$('#mapRegion').value));draw(id!=='mapCluster')}));
 $$('[data-map-status]').forEach(b=>b.onclick=()=>{$('#mapStatus').value=b.dataset.mapStatus;$$('[data-map-status]').forEach(x=>x.classList.toggle('active',x===b));draw(true)});
 $$('[data-map-region]').forEach(b=>b.onclick=()=>{$('#mapRegion').value=$('#mapRegion').value===b.dataset.mapRegion?'':b.dataset.mapRegion;$$('[data-map-region]').forEach(x=>x.classList.toggle('active',x.dataset.mapRegion===$('#mapRegion').value));draw(true)});
 $$('[data-map-pane]').forEach(b=>b.onclick=()=>{const shell=$('.mapExperienceV55');$$('[data-map-pane]').forEach(x=>x.classList.toggle('active',x===b));shell?.classList.toggle('showListV53',b.dataset.mapPane==='list');shell?.classList.toggle('showMapV53',b.dataset.mapPane==='map');setTimeout(()=>currentMap.invalidateSize(),80)});
 $('#mapClear').onclick=()=>{$('#mapSearch').value='';$('#mapCat').value='';$('#mapStatus').value='';if($('#mapRegion'))$('#mapRegion').value='';if($('#mapAgency'))$('#mapAgency').value='';if($('#mapOpenOnly'))$('#mapOpenOnly').checked=false;if($('#mapCluster'))$('#mapCluster').checked=true;userPoint=null;if(userLayer){currentMap.removeLayer(userLayer);userLayer=null}$$('[data-map-status]').forEach(x=>x.classList.toggle('active',x.dataset.mapStatus===''));$$('[data-map-region]').forEach(x=>x.classList.remove('active'));const hint=$('#mapDistanceHint');if(hint)hint.textContent='Agrupamento automático protege desempenho em escalas amplas.';draw(true)};
 $('#mapFit')?.addEventListener('click',()=>{if(lastRows.length)currentMap.fitBounds(L.latLngBounds(lastRows.map(o=>[o.lat,o.lng])).pad(.18),{maxZoom:15});else currentMap.setView(PIRACICABA,12)});
 $('#mapFocus')?.addEventListener('click',()=>{const active=card.classList.toggle('mapFocusModeV53');document.body.classList.toggle('mapFocusOpenV53',active);$('#mapFocus').setAttribute('aria-label',active?'Sair do modo foco':'Abrir mapa em modo foco');setTimeout(()=>currentMap.invalidateSize(),120)});
 $('#mapShare')?.addEventListener('click',async()=>{syncUrl();try{await navigator.clipboard.writeText(location.href);toast('Visão do mapa copiada com os filtros atuais.')}catch{toast('Não foi possível copiar o link.')}});
 $('#mapLocate')?.addEventListener('click',()=>{if(!navigator.geolocation)return toast('Geolocalização indisponível neste navegador.');const btn=$('#mapLocate'),old=btn.innerHTML;btn.disabled=true;btn.textContent='Localizando…';navigator.geolocation.getCurrentPosition(pos=>{userPoint={lat:pos.coords.latitude,lng:pos.coords.longitude};if(userLayer)currentMap.removeLayer(userLayer);userLayer=L.circleMarker([userPoint.lat,userPoint.lng],{radius:8,color:'#07383a',weight:3,fillColor:'#bff054',fillOpacity:1}).addTo(currentMap).bindPopup('Sua localização aproximada');const hint=$('#mapDistanceHint');if(hint)hint.textContent='Resultados ordenados pela distância até você.';draw(false);currentMap.flyTo([userPoint.lat,userPoint.lng],14,{duration:.7});btn.disabled=false;btn.innerHTML=old},()=>{toast('Não foi possível obter sua localização.');btn.disabled=false;btn.innerHTML=old},{enableHighAccuracy:false,timeout:8000})});
