 fetch(TERRITORY_URL,{cache:'no-cache'}).then(r=>r.ok?r.json():Promise.reject()).then(data=>{const idx=new Map();for(const reg of data.administrativeRegions||[])for(const raw of reg.neighborhoods||[]){for(const name of [raw,raw.replace(/^Parte do /i,'')]){const key=normText(name),arr=idx.get(key)||[];if(!arr.includes(reg.id))arr.push(reg.id);idx.set(key,arr)}}territoryIndex=idx;if($('#mapRegion'))$('#mapRegion').disabled=false;draw(false)}).catch(()=>{});
